SELECT "t13"."order_number", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."on_hand", "t13"."outage", "t13"."short", 'hold_sales' AS "route", 'shortfall' AS "context"
FROM (SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
        FROM (SELECT "t9"."order_number", "t9"."customer", "t9"."channel", "t9"."fulfilling_warehouse", "t9"."value", "t9"."placed_date", "t9"."state", "t9"."line_no", "t9"."item", "t9"."quantity", "t9"."unit_price", "t9"."ext_sales_price", "t9"."warehouse", "t9"."sold_date", "t9"."customer0", "t9"."channel0", "t9"."as_of_date", "t9"."quantity_on_hand", "t9"."_ttrp_g_n9_0", "t9"."_ttrp_g_n9_1", "t9"."_ttrp_latest_n9", "t10"."warehouse" AS "warehouse0", "t10"."from_date", "t10"."to_date", "t10"."reason", COALESCE("t9"."quantity_on_hand", 0) AS "on_hand", "t10"."warehouse" IS NOT NULL AS "outage"
                FROM (SELECT *
                        FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "t2"."line_no", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."ext_sales_price", "t2"."warehouse", "t2"."sold_date", "t2"."customer0", "t2"."channel0", "t2"."as_of_date", "t2"."quantity_on_hand", "t2"."_ttrp_g_n9_0", "t2"."_ttrp_g_n9_1", "t7"."_ttrp_latest_n9"
                                FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t1"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t1"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t1"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t1"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t0"
                                                    INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                                            LEFT JOIN "inventory" ON "t1"."item" = "inventory"."item" AND "t1"."warehouse" = "inventory"."warehouse") AS "t2"
                                    INNER JOIN (SELECT CASE WHEN "t5"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t5"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                        FROM (SELECT "t4"."order_number", "t4"."customer", "t4"."channel", "t4"."fulfilling_warehouse", "t4"."value", "t4"."placed_date", "t4"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t4"
                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t4"."order_number" = "sales_line0"."order_number") AS "t5"
                                            LEFT JOIN "inventory" AS "inventory0" ON "t5"."item" = "inventory0"."item" AND "t5"."warehouse" = "inventory0"."warehouse"
                                        GROUP BY CASE WHEN "t5"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."order_number" AS VARCHAR) END, CASE WHEN "t5"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t5"."line_no" AS VARCHAR) END) AS "t7" ON "t2"."_ttrp_g_n9_0" = "t7"."_ttrp_g_n9_0" AND "t2"."_ttrp_g_n9_1" = "t7"."_ttrp_g_n9_1") AS "t8"
                        WHERE "t8"."as_of_date" = "t8"."_ttrp_latest_n9" OR "t8"."_ttrp_latest_n9" IS NULL) AS "t9"
                    LEFT JOIN (SELECT *
                        FROM "warehouse_outage"
                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t10" ON "t9"."warehouse" = "t10"."warehouse") AS "t11"
        WHERE "t11"."outage" OR "t11"."on_hand" < "t11"."quantity") AS "t13"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t44"."order_number", "t44"."customer", "t44"."channel", "t44"."fulfilling_warehouse", "t44"."value", "t44"."placed_date", "t44"."state", COALESCE("t44"."n_short", 0) AS "n_short", COALESCE("t44"."n_price", 0) AS "n_price", COALESCE("t50"."n_due", 0) AS "n_due"
                FROM (SELECT "t32"."order_number", "t32"."customer", "t32"."channel", "t32"."fulfilling_warehouse", "t32"."value", "t32"."placed_date", "t32"."state", "t32"."n_short", "t43"."n_price"
                        FROM (SELECT "t15"."order_number", "t15"."customer", "t15"."channel", "t15"."fulfilling_warehouse", "t15"."value", "t15"."placed_date", "t15"."state", "t31"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t15"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t26"."order_number", "t26"."customer", "t26"."channel", "t26"."fulfilling_warehouse", "t26"."value", "t26"."placed_date", "t26"."state", "t26"."line_no", "t26"."item", "t26"."quantity", "t26"."unit_price", "t26"."ext_sales_price", "t26"."warehouse", "t26"."sold_date", "t26"."customer0", "t26"."channel0", "t26"."as_of_date", "t26"."quantity_on_hand", "t26"."_ttrp_g_n9_0", "t26"."_ttrp_g_n9_1", "t26"."_ttrp_latest_n9", "t27"."warehouse" AS "warehouse0", "t27"."from_date", "t27"."to_date", "t27"."reason", COALESCE("t26"."quantity_on_hand", 0) AS "on_hand", "t27"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT *
                                                        FROM (SELECT "t19"."order_number", "t19"."customer", "t19"."channel", "t19"."fulfilling_warehouse", "t19"."value", "t19"."placed_date", "t19"."state", "t19"."line_no", "t19"."item", "t19"."quantity", "t19"."unit_price", "t19"."ext_sales_price", "t19"."warehouse", "t19"."sold_date", "t19"."customer0", "t19"."channel0", "t19"."as_of_date", "t19"."quantity_on_hand", "t19"."_ttrp_g_n9_0", "t19"."_ttrp_g_n9_1", "t24"."_ttrp_latest_n9"
                                                                FROM (SELECT "t18"."order_number", "t18"."customer", "t18"."channel", "t18"."fulfilling_warehouse", "t18"."value", "t18"."placed_date", "t18"."state", "t18"."line_no", "t18"."item", "t18"."quantity", "t18"."unit_price", "t18"."ext_sales_price", "t18"."warehouse", "t18"."sold_date", "t18"."customer0", "t18"."channel0", "inventory1"."as_of_date", "inventory1"."quantity_on_hand", CASE WHEN "t18"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t18"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t18"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t18"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                        FROM (SELECT "t17"."order_number", "t17"."customer", "t17"."channel", "t17"."fulfilling_warehouse", "t17"."value", "t17"."placed_date", "t17"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                        FROM "order"
                                                                                        WHERE "state" IN ('held', 'placed')) AS "t17"
                                                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t17"."order_number" = "sales_line1"."order_number") AS "t18"
                                                                            LEFT JOIN "inventory" AS "inventory1" ON "t18"."item" = "inventory1"."item" AND "t18"."warehouse" = "inventory1"."warehouse") AS "t19"
                                                                    INNER JOIN (SELECT CASE WHEN "t22"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t22"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t22"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t22"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory2"."as_of_date") AS "_ttrp_latest_n9"
                                                                        FROM (SELECT "t21"."order_number", "t21"."customer", "t21"."channel", "t21"."fulfilling_warehouse", "t21"."value", "t21"."placed_date", "t21"."state", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."quantity", "sales_line2"."unit_price", "sales_line2"."ext_sales_price", "sales_line2"."warehouse", "sales_line2"."sold_date", "sales_line2"."customer" AS "customer0", "sales_line2"."channel" AS "channel0"
                                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                        FROM "order"
                                                                                        WHERE "state" IN ('held', 'placed')) AS "t21"
                                                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t21"."order_number" = "sales_line2"."order_number") AS "t22"
                                                                            LEFT JOIN "inventory" AS "inventory2" ON "t22"."item" = "inventory2"."item" AND "t22"."warehouse" = "inventory2"."warehouse"
                                                                        GROUP BY CASE WHEN "t22"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t22"."order_number" AS VARCHAR) END, CASE WHEN "t22"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t22"."line_no" AS VARCHAR) END) AS "t24" ON "t19"."_ttrp_g_n9_0" = "t24"."_ttrp_g_n9_0" AND "t19"."_ttrp_g_n9_1" = "t24"."_ttrp_g_n9_1") AS "t25"
                                                        WHERE "t25"."as_of_date" = "t25"."_ttrp_latest_n9" OR "t25"."_ttrp_latest_n9" IS NULL) AS "t26"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t27" ON "t26"."warehouse" = "t27"."warehouse") AS "t28"
                                        WHERE "t28"."outage" OR "t28"."on_hand" < "t28"."quantity"
                                        GROUP BY "order_number") AS "t31" ON "t15"."order_number" = "t31"."order_number") AS "t32"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t35"."order_number", "t35"."line_no", "t35"."item", "t35"."unit_price", "t35"."customer", "t35"."channel", "t35"."placed_date", "t39"."order_number" AS "order_number0", "t39"."line_no" AS "line_no0", "t39"."price"
                                        FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t34"."customer", "t34"."channel", "t34"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t34"
                                                    INNER JOIN "sales_line" AS "sales_line3" ON "t34"."order_number" = "sales_line3"."order_number") AS "t35"
                                            INNER JOIN (SELECT "t38"."order_number", "t38"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line4"."order_number", "sales_line4"."line_no", "sales_line4"."item", "sales_line4"."unit_price", "t37"."customer", "t37"."channel", "t37"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t37"
                                                            INNER JOIN "sales_line" AS "sales_line4" ON "t37"."order_number" = "sales_line4"."order_number") AS "t38"
                                                    LEFT JOIN "customer_price" ON "t38"."item" = "customer_price"."item" AND "t38"."customer" = "customer_price"."customer" AND "t38"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t38"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t38"."item" = "price_list"."item" AND "t38"."channel" = "price_list"."channel" AND "t38"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t38"."placed_date" <= "price_list"."valid_to")) AS "t39" ON "t35"."order_number" = "t39"."order_number" AND "t35"."line_no" = "t39"."line_no") AS "t40"
                                WHERE "t40"."price" IS NULL OR ABS("t40"."unit_price" - "t40"."price") > :tolerance
                                GROUP BY "order_number0") AS "t43" ON "t32"."order_number" = "t43"."order_number") AS "t44"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t46"."order_number", "t46"."customer", "t46"."channel", "t46"."fulfilling_warehouse", "t46"."value", "t46"."placed_date", "t46"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t46"
                                    INNER JOIN "invoice" ON "t46"."customer" = "invoice"."customer") AS "t47"
                        WHERE "t47"."status" = 'open' AND "t47"."due" < :as_of
                        GROUP BY "order_number") AS "t50" ON "t44"."order_number" = "t50"."order_number") AS "t51"
        WHERE "t51"."n_short" > 0 OR "t51"."n_price" > 0
        GROUP BY "order_number") AS "t54" ON "t13"."order_number" = "t54"."order_number"
